from solution import dict_filter


def test_issue_example():
    """Example keeps values 175,180,190 and drops 165 for threshold 170."""
    # 175 > 170 keep; 180 > 170 keep; 165 < 170 drop; 190 > 170 keep
    assert dict_filter({'Cierra Vega': 175, 'Alden Cantrell': 180, 'Kierra Gentry': 165, 'Pierre Cox': 190}, 170) == {'Cierra Vega': 175, 'Alden Cantrell': 180, 'Pierre Cox': 190}


def test_issue_single_value_above_kept():
    """Filter keeps a single value greater than the threshold."""
    # 99 > 10 keep
    assert dict_filter({'x': 99}, 10) == {'x': 99}


def test_issue_single_value_below_dropped():
    """Filter drops a single value less than the threshold."""
    # 1 < 10 drop
    assert dict_filter({'x': 1}, 10) == {}


def test_issue_value_just_above_threshold():
    """Filter keeps a value just above the threshold."""
    # 101 > 100 keep (101 == 100 + 1)
    assert dict_filter({'a': 101}, 100) == {'a': 101}


def test_issue_value_just_below_threshold():
    """Filter drops a value just below the threshold."""
    # 99 < 100 drop (99 == 100 - 1)
    assert dict_filter({'a': 99}, 100) == {}


def test_issue_empty_dict():
    """Filtering an empty dictionary returns an empty dictionary."""
    # no entries to compare against 170
    assert dict_filter({}, 170) == {}


def test_issue_all_below_returns_empty():
    """Filtering when every value is below threshold returns empty dict."""
    # 1 < 10 drop; 2 < 10 drop; 3 < 10 drop
    assert dict_filter({'a': 1, 'b': 2, 'c': 3}, 10) == {}


def test_issue_all_above_keeps_all():
    """Filtering when every value is above threshold keeps everything."""
    # 11 > 10 keep; 12 > 10 keep
    assert dict_filter({'a': 11, 'b': 12}, 10) == {'a': 11, 'b': 12}


def test_contract_returns_dict():
    """Return value is a dictionary."""
    # 20 > 10 keep
    result = dict_filter({'a': 20}, 10)
    assert isinstance(result, dict)
    assert result == {'a': 20}


def test_contract_preserves_key_value_pairs():
    """Kept entries keep their original keys and values."""
    # 30 > 10 keep; 5 < 10 drop
    assert dict_filter({'a': 30, 'b': 5}, 10) == {'a': 30}
